sys_script_client.script:
function onLoad() {

    // Hide Territory option by default
    //g_form.removeOption('business_dimension', 'territory');
    var ga = new GlideAjax('IncentNowClientUtils');
    ga.addParam('sysparm_name', 'isSalesTerritoryExtensionActive');

    ga.getXMLAnswer(function(answer) {
            if (answer == 'true') {
                g_form.addOption('business_dimension', 'territory', 'Territory');
            } else if (g_form.getValue('business_dimension') != 'territory') {
                g_form.removeOption('business_dimension', 'territory');
            }
            // Safety: if existing value is Territory, clear it
//             if (g_form.getValue('business_dimension') == 'territory') {
//      g_form.setValue('business_dimension', 'business_unit');
//  }


    });
}
